int get_ancillary(spng_ctx *ctx)
{
    if(ctx == NULL) return 1;
    if(ctx->data == NULL) return 1;
    if(!ctx->valid_state) return SPNG_EBADSTATE;

    int ret;
    if(!ctx->first_idat.offset)
    {
        ret = get_ancillary_data_first_idat(ctx);
        if(ret)
        {
            ctx->valid_state = 0;
            return ret;
        }
    }

    return 0;
}
